(1, 'task_assigned', 'New Task Assigned: {{task_title}}', '<p>Hello {{staff_name}},</p>\r\n<p>You have been assigned a new task: <strong>{{task_title}}</strong>.</p>\r\n<p><strong>Category:</strong> {{task_category}}</p>\r\n<p>Please log in to your dashboard to view the details and start working on it.</p>', '2026-08-23 11:14:28', '2026-08-24 05:57:31'),
(4, 'task_approved', 'Task Approved: {{task_title}}', '<p>Hello {{staff_name}},</p>\r\n<p>Great news! Your task <strong>{{task_title}}</strong> has been reviewed and <strong>Approved</strong>.</p>\r\n<p>Keep up the good work!</p>', '2026-08-24 05:57:31', '2026-08-24 05:57:31'),
(5, 'task_rejected', 'Revision Required: {{task_title}}', '<p>Hello {{staff_name}},</p>\r\n<p>Your task <strong>{{task_title}}</strong> has been reviewed and requires <strong>Revision (Rejected)</strong>.</p>\r\n<p><strong>Reason for rejection:</strong><br/>\r\n{{rejection_reason}}</p>\r\n{{rejection_image_html}}\r\n<p>Please log in to your dashboard, make the necessary corrections, and resubmit.</p>', '2026-08-24 05:57:31', '2026-08-24 05:57:31');
