INSERT INTO `tasks` (`id`, `title`, `description`, `checklists`, `ref_image`, `visual_image`, `ref_links`, `created_by`, `assigned_to`, `category`, `department_id`, `priority`, `status`, `is_self_created`, `timer_status`, `session_start_time`, `total_time_spent`, `submission_link`, `created_at`, `updated_at`, `submitted_at`, `rejection_reason`, `rejection_image`, `assign_date`, `deadline`, `deadline_time`, `reviewed_by`, `reviewed_at`, `rejected_by`, `rejected_at`) VALUES
(3, 'Real Estate Promotional Flyer Design', '<p><strong>Create the design as a fully editable, layered PSD file. Keep all text, shapes, images, buttons, icons, and decorative elements on separate layers/groups so the entire design can be easily edited in Adobe Photoshop.</strong></p>', NULL, '[\"uploads/task_images/task_6a8283011ae46.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 5, 'https://drive.google.com/drive/folders/1bH6heqP4raczFcXH4h4T_Tx5zQDm5fLF?usp=sharing', '2026-08-16 03:41:58', '2026-08-26 08:53:21', '2026-08-19 09:25:25', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-22 05:24:17', NULL, NULL),
(4, 'Creative Business Solutions Promotional Flyer Design', '<p>Keep <strong data-start=\"921\" data-end=\"1038\">all text, images, shapes, waves, badges, buttons, icons, and branding elements on separate editable layers/groups</strong>. Do not flatten the design. The final PSD should be easy to modify in Adobe Photoshop and closely match the provided reference in layout, colors, proportions, and overall appearance.</p>', NULL, '[\"uploads/task_images/task_6a82834a776ae.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 3, 'https://drive.google.com/drive/folders/1sN8JU5GLrMJnXyW7-KM-NzUk9cBUNay6?usp=sharing', '2026-08-16 03:43:53', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:49:49', NULL, NULL),
(5, 'Modern House for Sale Flyer Design', '<p>Recreate the provided real estate flyer as a <strong data-start=\"104\" data-end=\"135\">fully editable, layered PSD</strong>. Match the reference layout, dark green/yellow color scheme, typography, curved wave elements, house images, logo area, social icons, features list, and <strong data-start=\"289\" data-end=\"301\">CALL NOW</strong> section. Keep all text, images, shapes, and design elements on separate editable layers/groups.</p>', NULL, '[\"uploads/task_images/task_6a8283c1da0ac.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 4, 'https://drive.google.com/drive/folders/1fwlCPxniOc5tQOpeCdytWM6Mh__kDmi7?usp=sharing', '2026-08-16 03:45:11', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:50:27', NULL, NULL),
(6, 'Luxury Real Estate Property Flyer', '<div class=\"flex max-w-full flex-col gap-4 grow\"><div data-message-author-role=\"assistant\" data-message-id=\"bc5896f1-0c82-4015-bfb6-935f5c9310b7\" dir=\"auto\" data-message-model-slug=\"gpt-5-6\" class=\"min-h-8 text-message relative flex w-full flex-col items-end gap-2 text-start break-words whitespace-normal outline-none keyboard-focused:focus-ring [.text-message+&amp;]:mt-1\" data-turn-start-message=\"true\" tabindex=\"0\"><div class=\"flex w-full flex-col gap-1 empty:hidden\"><div class=\"markdown prose dark:prose-invert wrap-break-word w-full light markdown-new-styling\"><p data-start=\"59\" data-end=\"397\" data-is-last-node=\"\" data-is-only-node=\"\" class=\"PDq2pG_selectionAnchorContainer\">Recreate the provided real estate flyer as a <strong data-start=\"104\" data-end=\"135\">fully editable, layered PSD</strong>. Match the reference layout, dark green/yellow color scheme, typography, curved wave elements, house images, logo area, social icons, features list, and <strong data-start=\"289\" data-end=\"301\">CALL NOW</strong> section. Keep all text, images, shapes, and design elements on separate editable layers/groups.</p></div></div></div></div><div class=\"z-0 flex min-h-[46px] justify-start\"><br></div><div class=\"mt-6\"><div class=\"flex flex-col items-center gap-3 px-4 pb-1 text-center\"><div class=\"text-token-text-secondary text-sm leading-5 [text-wrap:pretty]\"><br></div><br></div><br></div>', NULL, '[\"uploads/task_images/task_6a8283f34dbd5.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 3, 'https://drive.google.com/drive/folders/1JkZ_wMyGLlb8AovCozRFt6HaixBWcix3?usp=sharing', '2026-08-16 03:46:36', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:52:55', NULL, NULL),
(7, 'Modern Property Promotion Flyer', '<p>Create a clean and attractive house-for-sale flyer based on the reference design. Include property images, home features, contact details, branding, and <strong>CTA</strong>. Provide a fully layered, editable <strong>PSD </strong>file.</p>', NULL, '[\"uploads/task_images/task_6a828442d93af.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 2, 'https://drive.google.com/drive/folders/1waZOYphaYI-2BG4Gej3l8NmziMtrVXof?usp=sharing', '2026-08-16 03:47:50', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:53:32', NULL, NULL),
(8, 'Premium Modern Home Advertisement', '<p data-start=\"905\" data-end=\"1181\" class=\"PDq2pG_selectionAnchorContainer\">Recreate the reference as a sophisticated real estate advertisement using bold typography, curved graphic elements, green/gold accents, architectural imagery, and organized property information. Submit as a fully editable <strong>Photoshop PSD</strong>.</p>\n<h3 data-section-id=\"1dqjthq\" data-start=\"1183\" data-end=\"1211\"><br></h3>', NULL, '[\"uploads/task_images/task_6a8284744f357.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 17, 'https://drive.google.com/drive/folders/1uSi6XhpPG8wR6IMkn7NZhwru9JV43BG2?usp=sharing', '2026-08-16 03:48:41', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:54:01', NULL, NULL),
(9, 'Real Estate House Sale Flyer', '<p>Recreate the provided reference design in <strong data-start=\"1289\" data-end=\"1312\">editable PSD format</strong>, maintaining the overall composition, colors, typography, image placement, decorative curves, feature section, logo area, social icons, and contact/CTA section. Keep every major element on separate layers.</p>', NULL, '[\"uploads/task_images/task_6a8284a848a9c.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 4, 'https://drive.google.com/drive/folders/1kquUi1_CuqeYO5VHhTnkH6YA6my17egJ?usp=sharing', '2026-08-16 03:49:17', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:55:20', NULL, NULL),
(10, 'Modern House Sale Advertisement', '<p>Create a premium real estate flyer for a modern home, matching the reference style, and deliver it as a fully editable layered <strong>PSD</strong>.</p>', NULL, '[]', '[\"uploads\\/task_images\\/task_6a8bcd046abe2.webp\"]', '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 15, 'https://drive.google.com/drive/folders/1AtYNlnomi2JjhqmZMeoPcTzFQnkJWuCF?usp=sharing', '2026-08-16 03:49:50', '2026-08-26 08:53:21', '2026-08-19 09:27:09', NULL, NULL, '2026-08-16', NULL, NULL, 10, '2026-08-20 05:55:57', NULL, NULL),
