(43, 'Real Estate Social Media Post Template', '<p>{<br>  \"canvas_specifications\": {<br>    \"width_px\": 1080,<br>    \"height_px\": 1080,<br>    \"aspect_ratio\": \"1:1\",<br>    \"resolution_dpi\": 300,<br>    \"color_mode\": \"RGB\"<br>  },<br>  \"template_type\": \"Real Estate Social Media Flyer Template\",<br>  \"target_platform\": \"Freepik Contributor Asset\",<br>  \"color_scheme\": {<br>    \"primary_sky_blue\": \"#0090F8\",<br>    \"secondary_dark_navy\": \"#0C1B3B\",<br>    \"accent_white\": \"#FFFFFF\",<br>    \"text_dark_slate\": \"#333A48\",<br>    \"text_grey\": \"#717B8C\",<br>    \"background_light\": \"#FFFFFF\"<br>  },<br>  \"typography_specifications\": {<br>    \"fonts_used\": [<br>      {<br>        \"font_family\": \"Montserrat\",<br>        \"type\": \"Google Font\",<br>        \"weights\": [500, 600, 700, 800, 900]<br>      },<br>      {<br>        \"font_family\": \"Open Sans\",<br>        \"type\": \"Google Font\",<br>        \"weights\": [400, 600, 700]<br>      }<br>    ]<br>  },<br>  \"top_left_header\": {<br>    \"logo_group\": {<br>      \"icon\": {<br>        \"description\": \"Paper airplane geometric polygon logo mark\",<br>        \"icon_glyph\": \"\\\\f1d8\",<br>        \"color\": \"#0090F8\"<br>      },<br>      \"line_1\": {<br>        \"text\": \"Royal Place\",<br>        \"font_family\": \"Montserrat\",<br>        \"font_style\": \"Bold\",<br>        \"font_weight\": 700,<br>        \"font_size_px\": 28,<br>        \"text_color\": \"#333A48\"<br>      },<br>      \"line_2\": {<br>        \"text\": \"Real Estate Agency\",<br>        \"font_family\": \"Open Sans\",<br>        \"font_style\": \"SemiBold\",<br>        \"font_weight\": 600,<br>        \"font_size_px\": 14,<br>        \"text_color\": \"#717B8C\"<br>      }<br>    }<br>  },<br>  \"about_us_section\": {<br>    \"position\": \"Middle-Left (upper white area)\",<br>    \"header\": {<br>      \"part_1\": {<br>        \"text\": \"ABOUT \",<br>        \"font_family\": \"Montserrat\",<br>        \"font_style\": \"ExtraBold Uppercase\",<br>        \"font_weight\": 800,<br>        \"font_size_px\": 32,<br>        \"text_color\": \"#333A48\"<br>      },<br>      \"part_2\": {<br>        \"text\": \"US\",<br>        \"font_family\": \"Montserrat\",<br>        \"font_style\": \"ExtraBold Uppercase\",<br>        \"font_weight\": 800,<br>        \"font_size_px\": 32,<br>        \"text_color\": \"#0090F8\"<br>      }<br>    },<br>    \"body_copy\": {<br>      \"text\": \"Lorem ipsum dolor sit amet, consec tetuer adipiscing elit, sed diam is a nonummy nibh euismod tincidunt ut laoreet dolore magna aliquam erat volutpat. nonummy nibh euismod tincidunt ut laoreet dolore magna aliquam erat volutpat.\",<br>      \"font_family\": \"Open Sans\",<br>      \"font_style\": \"Regular\",<br>      \"font_weight\": 400,<br>      \"font_size_px\": 12,<br>      \"text_color\": \"#717B8C\",<br>      \"line_height_px\": 18<br>    }<br>  },<br>  \"main_headline_container\": {<br>    \"shape\": \"Diagonal polygon block with cyan-to-royal blue gradient fill\",<br>    \"gradient\": \"Linear (#00A2FF to #0077E6)\",<br>    \"position\": \"Bottom-Left quadrant\",<br>    \"line_1\": {<br>      \"text\": \"MODERN\",<br>      \"font_family\": \"Montserrat\",<br>      \"font_style\": \"ExtraBold Uppercase\",<br>      \"font_weight\": 800,<br>      \"font_size_px\": 64,<br>      \"text_color\": \"#FFFFFF\"<br>    },<br>    \"line_2\": {<br>      \"text\": \"HOME\",<br>      \"font_family\": \"Montserrat\",<br>      \"font_style\": \"Black Uppercase\",<br>      \"font_weight\": 900,<br>      \"font_size_px\": 80,<br>      \"text_color\": \"#FFFFFF\"<br>    },<br>    \"line_3\": {<br>      \"text\": \"FOR SALE\",<br>      \"font_family\": \"Montserrat\",<br>      \"font_style\": \"Black Uppercase\",<br>      \"font_weight\": 900,<br>      \"font_size_px\": 64,<br>      \"text_color\": \"#FFFFFF\"<br>    },<br>    \"sub_caption\": {<br>      \"text\": \"Lorem ipsum dolor sit amet, consec tetuer adipiscing elit, sed diam is a nonummy nibh euismod tincidunt ut laoreet dolore magna aliquam erat volutpat.\",<br>      \"font_family\": \"Open Sans\",<br>      \"font_style\": \"Regular\",<br>      \"font_weight\": 400,<br>      \"font_size_px\": 11,<br>      \"text_color\": \"#DCEEFF\",<br>      \"line_height_px\": 16<br>    }<br>  },<br>  \"image_frames\": [<br>    {<br>      \"frame_index\": 1,<br>      \"type\": \"Top-Right House Exterior Frame\",<br>      \"shape\": \"Diagonal polygon layout filling the upper-right half of the canvas\",<br>      \"position\": \"Top-Right to Center-Right\",<br>      \"content_description\": \"Front facade of a modern suburban two-story home at sunset with illuminated warm interior lights, grey siding, stone accents, two-car garage, and asphalt driveway\"<br>    }<br>  ],<br>  \"pricing_section\": {<br>    \"shape\": \"Diagonal dark navy polygon block\",<br>    \"background_color\": \"#0C1B3B\",<br>    \"position\": \"Middle-Right quadrant (below house exterior photo)\",<br>    \"text_group\": {<br>      \"line_1\": {<br>        \"text\": \"PRICE STARTS FROM\",<br>        \"font_family\": \"Montserrat\",<br>        \"font_style\": \"Bold Uppercase\",<br>        \"font_weight\": 700,<br>        \"font_size_px\": 18,<br>        \"text_color\": \"#FFFFFF\",<br>        \"letter_spacing_px\": 1<br>      },<br>      \"line_2\": {<br>        \"text\": \"$2,500,000\",<br>        \"font_family\": \"Montserrat\",<br>        \"font_style\": \"Black\",<br>        \"font_weight\": 900,<br>        \"font_size_px\": 44,<br>        \"text_color\": \"#FFFFFF\"<br>      }<br>    }<br>  },<br>  \"footer_content\": {<br>    \"position\": \"Bottom-Right on white background\",<br>    \"contact\": {<br>      \"icon\": {<br>        \"description\": \"White telephone handset inside cyan-blue rounded square container\",<br>        \"icon_glyph\": \"\\\\f095\",<br>        \"background_gradient\": \"Linear (#00A2FF to #0077E6)\"<br>      },<br>      \"label\": {<br>        \"text\": \"Call For Appointment\",<br>        \"font_family\": \"Open Sans\",<br>        \"font_style\": \"SemiBold\",<br>        \"font_weight\": 600,<br>        \"font_size_px\": 15,<br>        \"text_color\": \"#333A48\"<br>      },<br>      \"phone_number\": {<br>        \"text\": \"00 1234 5678\",<br>        \"font_family\": \"Montserrat\",<br>        \"font_style\": \"Black\",<br>        \"font_weight\": 900,<br>        \"font_size_px\": 24,<br>        \"text_color\": \"#333A48\"<br>      }<br>    }<br>  },<br>  \"decorative_background_shapes\": [<br>    {<br>      \"element\": \"Clean white base background polygon\",<br>      \"position\": \"Top-Left and Bottom-Right areas (#FFFFFF)\"<br>    },<br>    {<br>      \"element\": \"Sharp 45-degree diagonal seams splitting images and color blocks\",<br>      \"position\": \"Canvas diagonal grid\"<br>    }<br>  ]<br>}</p><p><br></p><p><br></p><p>Free Font Download Links (Google Fonts)<br><br>Montserrat Font Family: https://fonts.google.com/specimen/Montserrat<br><br>Open Sans Font Family: https://fonts.google.com/specimen/Open+Sans<br><br>Icon Links &amp; Glyph Codes (Photoshop / Illustrator)<br><br>FontAwesome Official Download: https://fontawesome.com/download<br><br>Paper Airplane Logo Icon: Flaticon SVG Link | Glyph: \\f1d8<br><br>Phone Call Icon: Flaticon SVG Link | Glyph: \\f095<br><br>Commercial-Use Placeholder Image Sources<br><br>Modern Suburban Exterior: https://unsplash.com/s/photos/modern-house<br><br>Luxury Real Estate Architecture: https://www.pexels.com/search/real%20estate%20exterior/<br><br>Photoshop Layer Organization Guide for 100% Freepik Approval<br><br>Layer Group Hierarchy Structure</p><p><br></p><p><br></p><p>???? [Template] - 1080x1080 Real Estate Flyer<br>├── ???? 01_TEXT &amp; CONTENT<br>│   ├── ???? 01_Header (Royal Place Logo)<br>│   ├── ???? 02_About Us Section Text<br>│   ├── ???? 03_Main Headline (Modern Home For Sale)<br>│   ├── ???? 04_Pricing Text ($2,500,000)<br>│   └── ???? 05_Footer Appointment &amp; Phone<br>├── ???? 02_BUTTONS &amp; ICONS<br>│   ├── ???? Phone Call Blue Icon Holder<br>│   └── ???? Paper Plane Vector Logo Glyph<br>├── ???? 03_IMAGE HOLDER (Smart Object)<br>│   └── ????️ [Smart Object] House Exterior Photo - Double Click to Edit<br>└── ???? 04_BACKGROUND &amp; VECTOR SHAPES<br>    ├── ???? Blue Gradient Headline Polygon (#00A2FF to #0077E6)<br>    ├── ???? Dark Navy Pricing Polygon (#0C1B3B)<br>    └── ???? Solid White Canvas Base (#FFFFFF)</p><p><br></p><p>Key Approval Checklist<br><br>Smart Object Placeholders: Convert the upper-right house exterior photograph into a dedicated Smart Object clipped to the diagonal vector mask labeled \"DOUBLE CLICK TO REPLACE IMAGE\".<br><br>Vector Shapes Only: Construct all angled polygon panels (blue headline container, dark navy price container, and phone icon box) using Photoshop\'s non-destructive Vector Shape Tools (U).<br><br>Editable Text Layers: Maintain all typography (headlines, \"About Us\" paragraph, price values, and contact details) as live, native editable text layers.<br><br>Layer Group Color Labels: Mark TEXT &amp; CONTENT in Red, BUTTONS &amp; ICONS in Green, IMAGE HOLDER in Yellow, and BACKGROUND in Blue.<br><br>Clean File Finalization: Delete all hidden test layers, unused paths, and stray guide lines before exporting the final .PSD file.</p>', NULL, '[\"uploads/task_images/task_6a82bde17c7c4.webp\",\"uploads/task_images/task_6a82bfb2345b1.webp\",\"uploads/task_images/task_6a82bfb249302.webp\",\"uploads/task_images/task_6a82bfb25f634.webp\"]', NULL, '[]', 1, 8, 'Graphic Design', 1, 'Medium', 'In Progress', 0, 'Stopped', NULL, 0, NULL, '2026-08-17 07:54:41', '2026-08-22 06:25:54', NULL, NULL, NULL, '2026-08-17', NULL, NULL, NULL, '2026-08-19 09:27:09', NULL, NULL),
(45, 'Real Estate Social Media Post Template', '<p><span data-slate-fragment=\"\" style=\"white-space: pre;\">{\n  \"canvas_specifications\": {\n    \"width_px\": 1080,\n    \"height_px\": 1080,\n    \"aspect_ratio\": \"1:1\",\n    \"resolution_dpi\": 300,\n    \"color_mode\": \"RGB\"\n  },\n  \"template_type\": \"Real Estate Social Media Flyer Template\",\n  \"target_platform\": \"Freepik Contributor Asset\",\n  \"color_scheme\": {\n    \"primary_dark_charcoal\": \"#232A35\",\n    \"accent_golden_yellow\": \"#FFB703\",\n    \"accent_white\": \"#FFFFFF\",\n    \"text_dark\": \"#2B323D\",\n    \"text_grey\": \"#6C757D\",\n    \"background_light\": \"#FFFFFF\"\n  },\n  \"typography_specifications\": {\n    \"fonts_used\": [\n      {\n        \"font_family\": \"Montserrat\",\n        \"type\": \"Google Font\",\n        \"weights\": [500, 600, 700, 800, 900]\n      },\n      {\n        \"font_family\": \"Open Sans\",\n        \"type\": \"Google Font\",\n        \"weights\": [400, 600, 700]\n      }\n    ]\n  },\n  \"top_left_header\": {\n    \"logo_group\": {\n      \"icon\": {\n        \"description\": \"Multi-tier modern building / house architectural outline\",\n        \"icon_glyph\": \"\\\\f1ad\",\n        \"color\": \"#232A35\"\n      },\n      \"line_1\": {\n        \"text\": \"LOGO HERE\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Bold Uppercase\",\n        \"font_weight\": 700,\n        \"font_size_px\": 24,\n        \"text_color\": \"#232A35\",\n        \"letter_spacing_px\": 1\n      },\n      \"line_2\": {\n        \"text\": \"SLOGAN HERE\",\n        \"font_family\": \"Open Sans\",\n        \"font_style\": \"SemiBold Uppercase\",\n        \"font_weight\": 600,\n        \"font_size_px\": 12,\n        \"text_color\": \"#6C757D\",\n        \"letter_spacing_px\": 1\n      }\n    }\n  },\n  \"main_headline_container\": {\n    \"shape\": \"Diagonal dark charcoal polygon card with rounded lower-right corner\",\n    \"background_color\": \