y\": {\n      \"font_family\": \"Montserrat\",\n      \"font_style\": \"Bold\",\n      \"font_weight\": 700,\n      \"font_size_px\": 26,\n      \"text_color\": \"#2B323D\"\n    },\n    \"column_left\": [\n      { \"text\": \"1 Kitchen rooms\", \"icon_glyph\": \"\\\\f14a\", \"icon_color\": \"#FFB703\", \"icon_bg\": \"#232A35\" },\n      { \"text\": \"5 Bed Rooms\", \"icon_glyph\": \"\\\\f14a\", \"icon_color\": \"#FFB703\", \"icon_bg\": \"#232A35\" },\n      { \"text\": \"1 Big Guest Room\", \"icon_glyph\": \"\\\\f14a\", \"icon_color\": \"#FFB703\", \"icon_bg\": \"#232A35\" }\n    ],\n    \"column_right\": [\n      { \"text\": \"1 Big Diningroom\", \"icon_glyph\": \"\\\\f14a\", \"icon_color\": \"#FFB703\", \"icon_bg\": \"#232A35\" },\n      { \"text\": \"1 Car Garage\", \"icon_glyph\": \"\\\\f14a\", \"icon_color\": \"#FFB703\", \"icon_bg\": \"#232A35\" },\n      { \"text\": \"1 Laundry Room\", \"icon_glyph\": \"\\\\f14a\", \"icon_color\": \"#FFB703\", \"icon_bg\": \"#232A35\" }\n    ],\n    \"item_typography\": {\n      \"font_family\": \"Open Sans\",\n      \"font_style\": \"SemiBold\",\n      \"font_weight\": 600,\n      \"font_size_px\": 15,\n      \"text_color\": \"#5A6578\",\n      \"line_height_px\": 28\n    }\n  },\n  \"pricing_section\": {\n    \"shape\": \"Diagonal dark charcoal polygon container aligned to bottom-right\",\n    \"background_color\": \"#232A35\",\n    \"position\": \"Bottom-Right corner\",\n    \"text_group\": {\n      \"line_1\": {\n        \"text\": \"Price Start from\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"SemiBold\",\n        \"font_weight\": 600,\n        \"font_size_px\": 22,\n        \"text_color\": \"#FFB703\"\n      },\n      \"line_2\": {\n        \"text\": \"$2300,000\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Black\",\n        \"font_weight\": 900,\n        \"font_size_px\": 42,\n        \"text_color\": \"#FFFFFF\"\n      }\n    }\n  },\n  \"footer_contact\": {\n    \"position\": \"Bottom-Left corner on white background\",\n    \"icon\": {\n      \"description\": \"Yellow phone handset inside solid dark rounded square badge\",\n      \"icon_glyph\": \"\\\\f095\",\n      \"color\": \"#FFB703\",\n      \"background_color\": \"#232A35\"\n    },\n    \"label\": {\n      \"text\": \"For More Info\",\n      \"font_family\": \"Open Sans\",\n      \"font_style\": \"SemiBold\",\n      \"font_weight\": 600,\n      \"font_size_px\": 14,\n      \"text_color\": \"#FFB703\"\n    },\n    \"phone_number\": {\n      \"text\": \"+000 000 0000\",\n      \"font_family\": \"Montserrat\",\n      \"font_style\": \"Bold\",\n      \"font_weight\": 700,\n      \"font_size_px\": 20,\n      \"text_color\": \"#232A35\"\n    }\n  },\n  \"decorative_background_shapes\": [\n    {\n      \"element\": \"Clean white header base\",\n      \"position\": \"Top-Left quadrant (#FFFFFF)\"\n    },\n    {\n      \"element\": \"Solid white base canvas\",\n      \"position\": \"Lower-Left features area (#FFFFFF)\"\n    }\n  ]\n}</span></p>', NULL, '[\"uploads/task_images/task_6a82c201ebef0.webp\",\"uploads/task_images/task_6a82e0db7b72b.webp\",\"uploads/task_images/task_6a82e0db8fd28.webp\",\"uploads/task_images/task_6a82e0dba35fb.webp\"]', NULL, '[]', 1, 5, 'Graphic Design', 1, 'Medium', 'Completed', 0, 'Stopped', NULL, 158016, 'https://drive.google.com/drive/folders/1yOIMyCAn-QQGqKqjMYZC7gqpdy5o_MXQ?usp=drive_link', '2026-08-17 08:09:06', '2026-08-26 08:53:21', '2026-08-19 04:53:36', NULL, NULL, '2026-08-17', NULL, NULL, 10, '2026-08-19 04:53:36', NULL, NULL),
