(61, 'Real Estate Social Media PostTemplate', '<p><span data-slate-fragment=\"\" style=\"white-space: pre;\">{\n  \"canvas_specifications\": {\n    \"width_px\": 1080,\n    \"height_px\": 1080,\n    \"aspect_ratio\": \"1:1\",\n    \"resolution_dpi\": 300,\n    \"color_mode\": \"RGB\"\n  },\n  \"template_type\": \"Real Estate Social Media Flyer Template\",\n  \"target_platform\": \"Freepik Contributor Asset\",\n  \"color_scheme\": {\n    \"primary_cyan_teal\": \"#00A8B5\",\n    \"secondary_lime_yellow\": \"#E8E74D\",\n    \"accent_dark_slate\": \"#1E2A38\",\n    \"accent_white\": \"#FFFFFF\",\n    \"text_grey\": \"#5A6578\",\n    \"overlay_dark_cyan\": \"#005662\"\n  },\n  \"typography_specifications\": {\n    \"fonts_used\": [\n      {\n        \"font_family\": \"Montserrat\",\n        \"type\": \"Google Font\",\n        \"weights\": [600, 700, 800, 900]\n      },\n      {\n        \"font_family\": \"Open Sans\",\n        \"type\": \"Google Font\",\n        \"weights\": [400, 600, 700]\n      }\n    ]\n  },\n  \"top_left_header\": {\n    \"logo_group\": {\n      \"icon\": {\n        \"description\": \"Cyan circular badge with house silhouette and wave curve cutout\",\n        \"icon_glyph\": \"\\\\f015\",\n        \"color\": \"#00A8B5\"\n      },\n      \"line_1\": {\n        \"text\": \"Modern House\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Bold\",\n        \"font_weight\": 700,\n        \"font_size_px\": 28,\n        \"text_color\": \"#1E2A38\"\n      },\n      \"line_2\": {\n        \"text\": \"Slogan Goes Here\",\n        \"font_family\": \"Open Sans\",\n        \"font_style\": \"Regular\",\n        \"font_weight\": 400,\n        \"font_size_px\": 16,\n        \"text_color\": \"#5A6578\"\n      }\n    }\n  },\n  \"main_headline_container\": {\n    \"shape\": \"Large circular overlay arc container in cyan (#00A8B5) with translucent blending over background house\",\n    \"position\": \"Left to Center canvas area\",\n    \"headline_gr