(115, 'Digital Marketing Agency Social Media PostTemplate', '<p><span data-slate-fragment=\"\" style=\"white-space: pre;\">{\n  \"canvas_specifications\": {\n    \"width_px\": 1080,\n    \"height_px\": 1080,\n    \"aspect_ratio\": \"1:1\",\n    \"resolution_dpi\": 300,\n    \"color_mode\": \"RGB\"\n  },\n  \"template_type\": \"Corporate / Digital Marketing Agency Social Media Flyer Template\",\n  \"target_platform\": \"Freepik Contributor Asset\",\n  \"color_scheme\": {\n    \"primary_leaf_green\": \"#2E9E44\",\n    \"secondary_dark_green\": \"#1B6E2C\",\n    \"accent_white\": \"#FFFFFF\",\n    \"ring_light_grey\": \"#E5E7EB\",\n    \"text_dark\": \"#2B323D\",\n    \"text_grey\": \"#5A6578\",\n    \"background_light\": \"#FFFFFF\"\n  },\n  \"typography_specifications\": {\n    \"fonts_used\": [\n      {\n        \"font_family\": \"Montserrat\",\n        \"type\": \"Google Font\",\n        \"weights\": [500, 600, 700, 800, 900]\n      },\n      {\n        \"font_family\": \"Great Vibes\",\n        \"type\": \"Google Font\",\n        \"weights\": [400]\n      },\n      {\n        \"font_family\": \"Open Sans\",\n        \"type\": \"Google Font\",\n        \"weights\": [400, 600]\n      }\n    ]\n  },\n  \"top_left_header\": {\n    \"logo_group\": {\n      \"icon\": {\n        \"description\": \"Two vertical green pill-shaped bar glyphs\",\n        \"icon_glyph\": \"\\\\f0c9\",\n        \"color\": \"#2E9E44\"\n      },\n      \"line_1\": {\n        \"text\": \"LOGO\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Bold Uppercase\",\n        \"font_weight\": 700,\n        \"font_size_px\": 24,\n        \"text_color\": \"#2B323D\",\n        \"letter_spacing_px\": 1\n      },\n      \"line_2\": {\n        \"text\": \"HERE\",\n        \"font_family\": \"Montserrat\",\n        \"font_style\": \"Regular Uppercase\",\n        \"font_weight\": 400,\n        \"font_size_px\": 20,\n        \"text_color\": \"#5A6578\",\n        \"letter_spacing_px\": 1\n    