(165, '02', '<p>{<br>  \"canvas_specifications\": {<br>    \"width_px\": 1080,<br>    \"height_px\": 1080,<br>    \"aspect_ratio\": \"1:1\",<br>    \"resolution_dpi\": 300,<br>    \"color_mode\": \"RGB\"<br>  },<br>  \"template_type\": \"Real Estate Social Media Flyer Template\",<br>  \"target_platform\": \"Freepik Contributor Asset\",<br>  \"color_scheme\": {<br>    \"primary_text_dark\": \"#FFFFFF\",<br>    \"background_dark\": \"#1A1A1A\",<br>    \"accent_blue\": \"#3897F0\",<br>    \"deco_text_grey\": \"#AAAAAA\",<br>    \"background_light\": \"#FFFFFF\"<br>  },<br>  \"typography_specifications\": {<br>    \"recommended_free_fonts\": [<br>      {<br>        \"font_family\": \"Montserrat\",<br>        \"weights\": [400, 500, 600, 700, 800, 900],<br>        \"link\": \"https://fonts.google.com/specimen/Montserrat\"<br>      },<br>      {<br>        \"font_family\": \"Poppins\",<br>        \"weights\": [400, 500, 600, 700, 800],<br>        \"link\": \"https://fonts.google.com/specimen/Poppins\"<br>      }<br>    ]<br>  },<br>  \"layer_hierarchy\": [<br>    {<br>      \"group_name\": \"Header\",<br>      \"position\": \"Top\",<br>      \"elements\": [<br>        {<br>          \"type\": \"Text Layer\",<br>          \"content\": \"LOGO HERE\",<br>          \"font_family\": \"Montserrat Medium\",<br>          \"font_size_px\": 28,<br>          \"color\": \"#FFFFFF\",<br>          \"alignment\": \"Center\"<br>        }<br>      ]<br>    },<br>    {<br>      \"group_name\": \"Main Title\",<br>      \"position\": \"Top-Mid\",<br>      \"elements\": [<br>        {<br>          \"type\": \"Text Layer\",<br>          \"content\": \"EXPLORE THE\",<br>          \"font_family\": \"Montserrat Bold\",<br>          \"color\": \"#FFFFFF\"<br>        },<br>        {<br>          \"type\": \"Text Layer\",<br>          \"content\": \"ELEGANT HOME\",<br>          \"font_family\": \"Montserrat Black\",<br>          \"color\": \"#3897F0\"<br>        },<br>        {<br>          \"type\"