(557, 'Travel Agency Flayer 001', '<p><span data-slate-fragment=\"\" style=\"white-space: pre;\">{\n  \"template_type\": \"Travel Sale Flyer\",\n  \"design_elements\": {\n    \"primary_colors\": [\"Dark Blue\", \"Yellow\", \"White\"],\n    \"shapes\": [\"Circles\", \"Curved waves\", \"Rectangles\"]\n  },\n  \"content_sections\": {\n    \"header\": {\n      \"company_logo_placeholder\": \"COMPANY NAME with diamond icon\",\n      \"main_title\": \"LET\'S TRAVEL\",\n      \"promotional_badge\": \"EN OF SEASON OFFER 50% OFF\"\n    },\n    \"imagery\": [\n      {\n        \"position\": \"Top Right (Large Circle)\",\n        \"description\": \"A man and a woman wearing sunglasses, taking a selfie and making a peace sign.\"\n      },\n      {\n        \"position\": \"Bottom Left (Small Circle)\",\n        \"description\": \"A couple looking at a map outdoors.\"\n      },\n      {\n        \"position\": \"Bottom Right (Small Circle)\",\n        \"description\": \"Two women, one holding a DSLR camera.\"\n      }\n    ],\n    \"middle_body\": {\n      \"call_to_action\": \"BIG OFFER BOOK NOW!\",\n      \"subtitle\": \"PLACE YOUR TITLE\",\n      \"description\": \"Placeholder text (Lorem ipsum...)\"\n    },\n    \"pricing_packages\": [\n      {\n        \"icon\": \"Airplane\",\n        \"title\": \"YOUR TITLE\",\n        \"price\": \"$999\",\n        \"duration\": \"3D / 2N\",\n        \"details\": \"ALL INCLUSIVE\"\n      },\n      {\n        \"icon\": \"Map Pin\",\n        \"title\": \"YOUR TITLE\",\n        \"price\": \"$999\",\n        \"duration\": \"3D / 2N\",\n        \"details\": \"ALL INCLUSIVE\"\n      },\n      {\n        \"icon\": \"Camera\",\n        \"title\": \"YOUR TITLE\",\n        \"price\": \"$999\",\n        \"duration\": \"3D / 2N\",\n        \"details\": \"ALL INCLUSIVE\"\n      }\n    ],\n    \"footer\": {\n      \"address\": \"Head Office location placeholder\",\n      \"website\": \"WWW.YOURWEB.COM\",\n      \"social_icons\": [\"Instagram\", \"Facebook\", \"Twitter\"]\n    }\n  }\n}</span></p>', '[]', '[]', '[\"uploads/task_images/task_6a8fdc669ef5b.webp\"]', '[]', 1, 6, 'Graphic Design', 1, 'Medium', 'In Progress', 0, 'Running', '2026-08-27 06:46:20', 0, NULL, '2026-08-27 06:43:56', '2026-08-27 06:46:20', NULL, NULL, NULL, '2026-08-27', NULL, NULL, NULL, NULL, NULL, NULL);
